// §14.4 Alertas de seguridad, inmediatas a administracion.
//
// Tres alertas de verdad:
//   PERSONA_NO_PERMITIDA   intento de ingreso denegado
//   PERMANENCIA_EXCEDIDA   alguien lleva mas tiempo dentro del esperado
//   SALIDA_NO_REGISTRADA   cierre automatico sin registro de salida
//
// Y dos avisos administrativos que §10 emite pero §14 no asigna a ningun
// flujo. Van aqui porque tienen el mismo destinatario, marcados con
// severidad 'aviso' para que no se confundan con una alerta.
//
// Las tres alertas las decide Spring: el umbral de permanencia, la hora del
// cierre automatico y el cotejo con la lista de no permitidos son reglas de
// negocio, no de transporte (§10).

const esperado = $env.PORTERIA_SECRET;
const admin = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
const ALERTAS = ['PERSONA_NO_PERMITIDA', 'PERMANENCIA_EXCEDIDA', 'SALIDA_NO_REGISTRADA'];
const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const evento = item.json.body || item.json;

  if (esperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== esperado) {
      throw new Error('X-Porteria-Secret invalido: evento descartado');
    }
  }

  const d = evento.datos || {};
  const apto = d.apartamento || 'sin apartamento';
  let asunto;
  let texto;

  switch (evento.tipo) {
    case 'PERSONA_NO_PERMITIDA':
      asunto = 'ALERTA: intento de ingreso de persona no permitida (' + apto + ')';
      texto = [
        'Se nego el ingreso de una persona que esta en la lista de no permitidos.',
        '',
        'Visitante: ' + d.visitanteNombre,
        'Apartamento destino: ' + apto,
        'Motivo del registro: ' + d.motivoRegistro,
        'Vigilante: ' + d.vigilante,
        '',
        'El intento quedo en bitacora. Confirma por radio con la porteria.',
      ].join('\n');
      break;

    case 'PERMANENCIA_EXCEDIDA':
      asunto = 'ALERTA: permanencia excedida en ' + apto;
      texto = [
        d.visitanteNombre + ' lleva mas tiempo del esperado en el apartamento ' + apto + '.',
        '',
        'Duracion esperada: ' + d.duracionEsperadaMin + ' minutos.',
        'Ingreso: ' + d.ingresoEn + '.',
        '',
        'Este aviso sale una sola vez por ingreso. Verifica por camaras o ronda.',
      ].join('\n');
      break;

    case 'SALIDA_NO_REGISTRADA':
      asunto = 'ALERTA: cierre automatico sin salida registrada (' + apto + ')';
      texto = [
        'El ingreso de ' + d.visitanteNombre + ' al apartamento ' + apto + ' se cerro',
        'automaticamente sin que la porteria registrara la salida.',
        '',
        'Ingreso: ' + d.ingresoEn + '.',
        '',
        'Revisa con el turno si la persona salio y no se registro.',
      ].join('\n');
      break;

    case 'DOCUMENTO_INDEXADO':
      asunto = 'Documento indexado: ' + d.titulo;
      texto = [
        '"' + d.titulo + '" (' + d.tipo + ', version ' + d.version + ') quedo indexado',
        'con ' + d.chunks + ' fragmentos. El asistente ya puede citarlo.',
      ].join('\n');
      break;

    case 'RAG_SIN_RESPUESTA':
      asunto = 'El asistente no encontro una respuesta';
      texto = [
        'Alguien pregunto algo que no esta en los documentos del conjunto:',
        '',
        '"' + d.pregunta + '"',
        '',
        'Rol: ' + d.rol + '. Mejor similitud encontrada: ' + d.mejorSimilitud + '.',
        '',
        'Esta es la lista de lo que convendria documentar. Tambien se ve en el',
        'panel de administracion, en Preguntas sin respuesta.',
      ].join('\n');
      break;

    default:
      console.log('Tipo que no corresponde a este flujo: ' + evento.tipo);
      continue;
  }

  salida.push({
    json: {
      tipo: evento.tipo,
      severidad: ALERTAS.includes(evento.tipo) ? 'alerta' : 'aviso',
      destinatario: admin,
      asunto,
      texto,
    },
  });
}

return salida;
